CREATE TRIGGER movement_no_exempt_insert BEFORE INSERT ON inventory_movements WHEN (SELECT inventory_exempt FROM ingredients WHERE id=NEW.ingredient_id)=1 BEGIN SELECT RAISE(ABORT,'inventory_exempt'); END;
UPDATE recipes SET instructions_json='["温かい炊飯済みの{{rice}}を用意する。ご飯の炊飯はこのレシピの調理時間に含まない。", "{{chicken}}を2cm角に切る。生肉に触れた手・包丁・まな板を洗う。", "{{cabbage}}を2cm幅に、{{onion}}を薄切りにする。{{ginger}}は皮を薄く除いてすりおろす。", "{{soy}}と{{sugar}}を混ぜ、すりおろしたしょうがを加えて生姜だれを作る。", "フライパンに{{oil}}を全量入れて中火で温める。鶏もも肉を重ならないように並べ、中火で約3分焼く。裏返して約3分焼く。", "キャベツ・たまねぎを加え、中火で約3分炒める。準備した生姜だれを全量加え、弱めの中火で約1分、全体に絡める。", "鶏もも肉の最も厚い部分が中心75℃に達してから1分以上加熱する。温度計で確認し、不足する場合は弱火で追加加熱する。焼き色だけで判断しない。", "用意したご飯と、出来上がったおかずを1人分として盛り付ける。加熱時間は目安なので、中心温度を優先する。"]' WHERE id='chicken-ginger';
UPDATE recipes SET instructions_json='["温かい炊飯済みの{{rice}}を用意する。ご飯の炊飯はこのレシピの調理時間に含まない。", "{{chicken}}を2cm角に切る。生肉に触れた手・包丁・まな板を洗う。", "{{cabbage}}を2cm幅に、{{carrot}}を厚さ2mm程度の短冊切りにする。", "{{miso}}と{{sugar}}を器でよく練り混ぜ、みそだれを作る。", "フライパンに{{oil}}を全量入れて中火で温める。鶏もも肉を重ならないように並べ、中火で約3分焼く。裏返して約3分焼く。", "キャベツ・にんじんを加え、中火で約3分炒める。にんじんが軟らかくなったら準備したみそだれを全量加え、弱火で約1分絡める。", "鶏もも肉の最も厚い部分が中心75℃に達してから1分以上加熱する。温度計で確認し、不足する場合は弱火で追加加熱する。焼き色だけで判断しない。", "用意したご飯と、出来上がったおかずを1人分として盛り付ける。加熱時間は目安なので、中心温度を優先する。"]' WHERE id='chicken-miso';
UPDATE recipes SET instructions_json='["温かい炊飯済みの{{rice}}を用意する。ご飯の炊飯はこのレシピの調理時間に含まない。", "{{chicken}}を2cm角に切る。生肉に触れた手・包丁・まな板を洗う。", "{{onion}}を薄切りに、{{carrot}}を厚さ2mm程度の短冊切りにする。", "{{curry}}と{{soy}}をそれぞれ計量しておく。カレー粉は焦げやすいので後半に加える。", "フライパンに{{oil}}を全量入れて中火で温める。鶏もも肉を重ならないように並べ、中火で約3分焼く。裏返して約3分焼く。", "たまねぎ・にんじんを加え、中火で約3分炒める。軟らかくなったら計量したカレー粉を全量加え、弱火で約30秒炒め、計量したしょうゆを全量加えて約1分絡める。", "鶏もも肉の最も厚い部分が中心75℃に達してから1分以上加熱する。温度計で確認し、不足する場合は弱火で追加加熱する。焼き色だけで判断しない。", "用意したご飯と、出来上がったおかずを1人分として盛り付ける。加熱時間は目安なので、中心温度を優先する。"]' WHERE id='chicken-curry';
UPDATE recipes SET instructions_json='["温かい炊飯済みの{{rice}}を用意する。ご飯の炊飯はこのレシピの調理時間に含まない。", "{{chicken}}を2cm角に切る。生肉に触れた手・包丁・まな板を洗う。", "{{tomato}}のへたを除いて1cm角に、{{onion}}を薄切りにする。", "{{soy}}を計量しておく。トマトの水分で蒸し煮にするので、水は加えない。", "鍋に{{oil}}を全量入れて中火で温める。鶏もも肉を重ならないように並べ、中火で約3分焼く。裏返して約3分焼く。", "たまねぎを加え、中火で約2分炒める。トマトと計量したしょうゆを全量加え、混ぜてふたをする。弱めの中火で約6分煮る。途中で混ぜ、焦げそうなら火を弱める。", "鶏もも肉の最も厚い部分が中心75℃に達してから1分以上加熱する。温度計で確認し、不足する場合は弱火で追加加熱する。焼き色だけで判断しない。", "用意したご飯と、出来上がったおかずを1人分として盛り付ける。加熱時間は目安なので、中心温度を優先する。"]' WHERE id='chicken-tomato';
UPDATE recipes SET instructions_json='["温かい炊飯済みの{{rice}}を用意する。ご飯の炊飯はこのレシピの調理時間に含まない。", "{{chicken}}を2cm角に切る。生肉に触れた手・包丁・まな板を洗う。", "{{broccoli}}を小房に分け、茎は薄切りにする。{{onion}}を薄切りにする。ブロッコリーを洗って水気の残ったまま耐熱容器に入れ、ふんわりラップをして600Wで約2分加熱する。熱い蒸気に注意してラップを外す。", "{{soy}}を計量しておく。", "フライパンに{{oil}}を全量入れて中火で温める。鶏もも肉を重ならないように並べ、中火で約3分焼く。裏返して約3分焼く。", "たまねぎを加え、中火で約2分炒める。下ゆでしたブロッコリーを加えて約1分炒め、計量したしょうゆを全量加えて約1分絡める。", "鶏もも肉の最も厚い部分が中心75℃に達してから1分以上加熱する。温度計で確認し、不足する場合は弱火で追加加熱する。焼き色だけで判断しない。", "用意したご飯と、出来上がったおかずを1人分として盛り付ける。加熱時間は目安なので、中心温度を優先する。"]' WHERE id='chicken-broccoli';
